<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Teacher,Department};use Illuminate\Http\Request;class TeacherController extends Controller{public function index(){return view('admin.teachers.index',['items'=>Teacher::with('department')->orderBy('sort')->paginate(30)]);}public function create(){return $this->form(new Teacher);}public function store(Request $r){Teacher::create($this->data($r));return redirect()->route('admin.teachers.index')->with('ok','Преподаватель добавлен');}public function edit(Teacher $teacher){return $this->form($teacher);}public function update(Request $r,Teacher $teacher){$teacher->update($this->data($r));return redirect()->route('admin.teachers.index')->with('ok','Сохранено');}public function destroy(Teacher $teacher){$teacher->delete();return back();}private function form($item){return view('admin.teachers.form',['item'=>$item,'departments'=>Department::orderBy('sort')->get()]);}private function data(Request $r){$d=$r->validate(['name'=>'required|max:255','department_id'=>'nullable|exists:departments,id','position'=>'nullable|max:255','bio'=>'nullable','sort'=>'nullable|integer']);$d['is_active']=$r->boolean('is_active');return $d;}}